/*
 * ISO 286 標準公差寬度（IT），獨立於孔／軸偏差資料。
 * 公稱尺寸 minMm／maxMm 的單位為 mm；widthUm 的單位為 μm。
 * 每筆適用範圍為 minMm < D <= maxMm；第一段為 0 < D <= 3。
 * 來源原表未將第一段拆成 0–1／1–3，也未以公式外推本檔數值。
 * 頁 436／437 的表列值已逐列轉錄；只展開原表，不計算孔或軸的 ES／EI。
 */
(function publishIsoItData() {
  'use strict';

  const sourceId = 'schaeffler-stt-2025-iso-it';
  const sources = [
    {
      id: sourceId,
      title: 'Schaeffler｜Technical Pocket Guide STT・ISO standard tolerances',
      url: 'https://www.schaeffler.com/remotemedien/media/_shared_media/08_media_library/01_publications/schaeffler_2/catalogue_1/downloads_6/stt_de_en.pdf',
      version: '4th, expanded edition, March 2025；原表依 ISO 286-1:2010',
      page: '印刷第 436–437 頁；第 436 頁主表及第 437 頁續表',
      scope: 'IT01、IT0、IT1–IT18；0 < D <= 500 mm。公稱尺寸下開上閉，公差寬度單位 μm；本資料只表示寬度，不指定公差帶位置或孔／軸限界。'
    }
  ];

  // 原表依序為 (0,3]、(3,6]、…、(400,500]；各列數值均為 μm。
  const sizeBoundsMm = [0, 3, 6, 10, 18, 30, 50, 80, 120, 180, 250, 315, 400, 500];
  const gradeRows = [
    ['01', [0.3, 0.4, 0.4, 0.5, 0.6, 0.6, 0.8, 1, 1.2, 2, 2.5, 3, 4]],
    ['0', [0.5, 0.6, 0.6, 0.8, 1, 1, 1.2, 1.5, 2, 3, 4, 5, 6]],
    ['1', [0.8, 1, 1, 1.2, 1.5, 1.5, 2, 2.5, 3.5, 4.5, 6, 7, 8]],
    ['2', [1.2, 1.5, 1.5, 2, 2.5, 2.5, 3, 4, 5, 7, 8, 9, 10]],
    ['3', [2, 2.5, 2.5, 3, 4, 4, 5, 6, 8, 10, 12, 13, 15]],
    ['4', [3, 4, 4, 5, 6, 7, 8, 10, 12, 14, 16, 18, 20]],
    ['5', [4, 5, 6, 8, 9, 11, 13, 15, 18, 20, 23, 25, 27]],
    ['6', [6, 8, 9, 11, 13, 16, 19, 22, 25, 29, 32, 36, 40]],
    ['7', [10, 12, 15, 18, 21, 25, 30, 35, 40, 46, 52, 57, 63]],
    ['8', [14, 18, 22, 27, 33, 39, 46, 54, 63, 72, 81, 89, 97]],
    ['9', [25, 30, 36, 43, 52, 62, 74, 87, 100, 115, 130, 140, 155]],
    ['10', [40, 48, 58, 70, 84, 100, 120, 140, 160, 185, 210, 230, 250]],
    ['11', [60, 75, 90, 110, 130, 160, 190, 220, 250, 290, 320, 360, 400]],
    ['12', [100, 120, 150, 180, 210, 250, 300, 350, 400, 460, 520, 570, 630]],
    ['13', [140, 180, 220, 270, 330, 390, 460, 540, 630, 720, 810, 890, 970]],
    ['14', [250, 300, 360, 430, 520, 620, 740, 870, 1000, 1150, 1300, 1400, 1550]],
    ['15', [400, 480, 580, 700, 840, 1000, 1200, 1400, 1600, 1850, 2100, 2300, 2500]],
    ['16', [600, 750, 900, 1100, 1300, 1600, 1900, 2200, 2500, 2900, 3200, 3600, 4000]],
    ['17', [1000, 1200, 1500, 1800, 2100, 2500, 3000, 3500, 4000, 4600, 5200, 5700, 6300]],
    ['18', [1400, 1800, 2200, 2700, 3300, 3900, 4600, 5400, 6300, 7200, 8100, 8900, 9700]]
  ];

  const records = gradeRows.flatMap(([grade, widths]) => widths.map((widthUm, index) => ({
    grade,
    minMm: sizeBoundsMm[index],
    maxMm: sizeBoundsMm[index + 1],
    widthUm,
    sourceId,
    pageLabel: index < 7 ? 'STT p.436' : 'STT p.437'
  })));

  const data = { sources, records };
  globalThis.ISO_IT_DATA = data;
  if (typeof window !== 'undefined') window.ISO_IT_DATA = data;
  if (typeof module === 'object' && module.exports) module.exports = data;
})();
